--- from: Assets/BundleResources/Prefabs/OverClub/OverseaClubPlayerController.prefab > name: PlayerInput
---@class OverseaClubPlayerInput
---@field Env                           	OverseaClubPlayerInput                  
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field touchInputSwitchableBH        	Engine.Modules.LuaBehaviour             	@ 0    -- TouchInputSwitchable
---@field keyboardInputSwitchableBH     	Engine.Modules.LuaBehaviour             	@ 1    -- KeyboardInputSwitchable
local OverseaClubPlayerInput = Class('OverseaClubPlayerInput')


function OverseaClubPlayerInput:__init()
    self.controller = nil
    self._currentChooseType = JumpHintType.None
    self._lastFrameHasMoveInput = false
end


function OverseaClubPlayerInput:__delete()
end



function OverseaClubPlayerInput:Init(catController, isUseManualViwRotateInPCMode_, isHideLeftJoystick_, joystickSize, joystickPosition )
    KTool.SetActive(self.controller.gameObject, true)

    self.catController    = catController
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    assert( self.keyboardInputSwitchableBH and self.touchInputSwitchableBH )

    self.keyboardInputSwitchable = DreamSpaceLuaUtils.GetLuaScr(self.keyboardInputSwitchableBH.gameObject, "Game.DreamSpace.CharacterController.KeyboardInputSwitchable" )
    self.touchInputSwitchable    = DreamSpaceLuaUtils.GetLuaScr(self.touchInputSwitchableBH.gameObject, "Game.DreamSpace.CharacterController.TouchInputSwitchable" )
    assert( self.keyboardInputSwitchable and self.touchInputSwitchable)

    JumpHint.SetCurrentChooseJump(function( jumpHintType_ )
        self._currentChooseType = jumpHintType_
    end)
    
    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()
    assert( not isNull(self.mCamera:GetComponent(typeof(CinemachineBrain))) )

    --- 确保 LeftJoystick 已准备好了:
    local LeftJoystickCanvasMgr = import('Game.DreamSpace.UI.LeftJoystickCanvasMgr'):GetInstance()
    LeftJoystickCanvasMgr:CheckOrInitSync(joystickSize, joystickPosition)
    LeftJoystickCanvasMgr.leftJoystickEnv:Active()

    LeftJoystickCanvasMgr:Show( (DreamSpaceStates.isWindowsPlatform == false) and (isHideLeftJoystick_ == false) )

    ---
    if DreamSpaceStates.isWindowsPlatform then
        print( "koko - OverseaClubPlayerInput -- pc --" )
        self.keyboardInputSwitchable:Init( self.switchablePlayerController, self, isUseManualViwRotateInPCMode_ )

    else 
        print( "koko - OverseaClubPlayerInput -- mobile --" )
        self.touchInputSwitchable:Init( self.switchablePlayerController, self )
    end
end

function OverseaClubPlayerInput:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function OverseaClubPlayerInput:Update()

    InputManager.SelfUpdate()

    -- 总屏蔽器:
    if DreamSpaceStates.IsInputForbidden() == true then 
        self.catController:MoveEnd()
        return
    end


    if DreamSpaceStates.isWindowsPlatform then
        -- 防止玩家误触发 alt 键:  
        -- todo: 但效果有效, 若按下 alt + w, 之后将导致猫不停向前走:
        local isCurrentFrameHasInput = (Input.touchCount>0) or (Input.anyKey)
        local isPressAlt = (Input.GetKey(KeyCode.LeftAlt) == true or Input.GetKey(KeyCode.RightAlt) == true)
        --if isPressAlt or (isCurrentFrameHasInput == false) then 

        if isPressAlt and Input.GetKey(KeyCode.W) then 
            print("触发 unity 组合键 alt + W")
            self.catController:MoveEnd()
            return
        end 

        if isPressAlt and (DreamSpaceStates.isUseAltKey ~= true) then 
            self.catController:MoveEnd()
            return
        end 
        -----
        self.keyboardInputSwitchable:SelfUpdate()
    end


    -- ===== Move: ===== 
    local hasMoveInput = InputManager.IsMoveInputNotZero()
    if not self._lastFrameHasMoveInput and hasMoveInput then
        -- ===== MoveStart: =====
        self.catController:MoveStart()
    end

    if self._lastFrameHasMoveInput and not hasMoveInput then
        -- ===== MoveEnd: =====
        self.catController:MoveEnd()
    end

    if hasMoveInput then
        -- ===== Move: =====

        -- 登记用户设备输入的移动值, 再拿出需要的移动值
        -- ( 有时 剧情系统会接管 角色的移动, 此时拿到的就是 程序生成的 移动值 )
        self.catController:Move( InputManager.GetMoveInput() )
    end
    self._lastFrameHasMoveInput = hasMoveInput

end

function OverseaClubPlayerInput:SetLock(lock)
    if lock then
        DreamSpaceStates.LockInput_ByFlag(DreamSpaceStates.InputLockState.Lock)
        local LeftJoystickCanvasMgr = import('Game.DreamSpace.UI.LeftJoystickCanvasMgr'):GetInstance()
        LeftJoystickCanvasMgr:Show(false)
    else
        DreamSpaceStates.LockInput_ByFlag(DreamSpaceStates.InputLockState.Unlock)
        local LeftJoystickCanvasMgr = import('Game.DreamSpace.UI.LeftJoystickCanvasMgr'):GetInstance()
        if not DreamSpaceStates.isWindowsPlatform then
            LeftJoystickCanvasMgr:Show(true)
        end
    end
end


function OverseaClubPlayerInput:CalculateCameraDirection(cameraRotation)
    local characterUp = Vector3.up
    
    local cameraPlanarDirection = Vector3.ProjectOnPlane(cameraRotation * Vector3.forward, characterUp).normalized
    if cameraPlanarDirection.sqrMagnitude < 0.00001 then
        cameraPlanarDirection = Vector3.ProjectOnPlane(cameraRotation * Vector3.up, characterUp).normalized
    end
    local cameraPlanarRotation = Quaternion.LookRotation(cameraPlanarDirection, characterUp)
    
    return cameraPlanarRotation
end




